"""Integrate the author's completed source-based semantic case report."""
import json
import re

def apply_report_addendum(content,work):
 a=json.loads((work/'protocol/author_manual_review_statement.json').read_text())
 assert a['number_of_reviewed_responses']==72 and sum(a['main_sample_findings'].values())==64
 start=content.index('## ۱۰. اجرای ضروری داوری معنایی انسانی');end=content.index('\n## ۱۱.',start)
 section='''## ۱۰. یافته‌های بررسی دستی معنایی نویسنده

نویسنده انجام بررسی دستی معنایی ۷۲ مورد پرسش–زمینه–پاسخ را اعلام و یافته‌های آن را ارائه کرده است. نمونهٔ اصلی شامل ۳۲ مورد از B و ۳۲ مورد از C است؛ هشت مورد تشخیصی B جدا بررسی شده‌اند. این بررسی پسینی و توسط نویسندهٔ آگاه از مطالعه انجام شده است. روش جاری، مطالعهٔ توافق بین ارزیابان یا برآورد دقت کل سیستم نیست؛ دامنهٔ ارزیابی جاری همان بررسی موردی نویسنده است.

مبنای قضاوت، معنای ادعا برای موجودیت، رابطه، تاریخ، واحد و قید سؤال بود. شواهد کامل مرجع از زمینهٔ واقعاً ارائه‌شده به مدل جدا دیده شد. اظهار عدد، نقل عدد، نفی آن و امتناع از پاسخ یک نتیجه محسوب نشد. دفتر انتخاب نمونه و یادداشت‌های کمکی دستیار با منشأ خود حفظ شده‌اند؛ جدول زیر خلاصهٔ یافته‌هایی است که نویسنده ارائه کرده و جدول نمره‌های فردی ساختگی برای انسان تولید نشده است.

| نتیجهٔ بررسی نسبت به شواهد منبع | تعداد در نمونهٔ اصلی |
|---|---:|
| پاسخ سازگار با منبع |۴۱|
| پاسخ مخالف منبع |۱۶|
| امتناع کامل، بدون ادعای پاسخ |۳|
| نامشخص |۴|
| مجموع |۶۴|

هشت مورد تشخیصی با نمونهٔ اصلی یکجا به‌عنوان درصد دقت حساب نمی‌شوند؛ این موارد با پرچم‌های خطا انتخاب شده‌اند. در دو مورد، پاسخ هم عدد را اظهار و هم از پاسخ مبتنی بر شواهد امتناع کرده است.

یافتهٔ نخست، پاسخ Koufax است که 1972 را بیان و سپس پاسخ براساس متن‌های داده‌شده را UNKNOWN اعلام می‌کند؛ معیار تطبیق عدد این تعارض را از بین نمی‌برد. یافتهٔ دوم، ابهام شخص در سؤال بازیگر دو سریال است: مرجع 1994 شخص مورد نظر annotation را دنبال می‌کند، در حالی که شواهد موجود تعبیر دیگری با 2013 را پشتیبانی می‌کند. یافتهٔ سوم، حفظ قید «بیش از ۳۰۰۰» است؛ این عبارت، شمار دقیق نیست و به‌تنهایی ۳۰۱۷ را غلط ثابت نمی‌کند. یافتهٔ چهارم، پاسخ‌های سازگار با مرجع است که در زمینهٔ واقعی مدل شاهد کافی ندارند. یافتهٔ پنجم، شاهد پاک جایگزین Operation Ladbroke برای 1943 است، با اینکه یکی از شواهد علامت‌گذاری‌شده حضور ندارد.

این یافته‌ها نشان می‌دهند صحت معنایی، پشتیبانی از زمینه و پوشش شواهد annotation باید جدا گزارش شوند. تمام ۱۸۸ نقل‌قول یادداشت‌های همراه با متن منبع یا پاسخ دقیق تطبیق داده شده‌اند. گزارش نویسنده در `manual_review/author_reported_findings.json` و شناسه‌ها، پاسخ‌ها، شواهد و منشأ یادداشت‌های کمکی در `assistant_review/` قابل بررسی‌اند. یافته‌های نمونه به‌عنوان نرخ پذیرش معنایی ادعای غلط مهاجم در تمام آزمایش تعمیم داده نشده‌اند.
'''
 content=content[:start]+section+content[end:]
 content=re.sub(r'دو موضوع هنوز باید صریح بماند\..*?(?=\n\n)', 'مرز شواهد اکنون روشن است: C مبنای اصلی نتیجه‌های آزمایشی است؛ B برای بازتحلیل و تشخیص خطای مرجع نگه داشته شده و A فقط زمینهٔ تاریخی است. بررسی دستی معنایی ۷۲موردی نویسنده در بخش دهم گزارش شده است. نبود آرشیو دقیق تاریخی و محدودیت تعمیم همچنان در حدود ادعای مربوط به خود بیان می‌شود؛ این دو محدودیت به نام رفع تجربی معرفی نشده‌اند.',content,flags=re.S)
 old='اصلاح ارجاع‌های شکلی و کتابنامه انجام می‌شود، اما این موارد نباید جای رفع ضعف روش را بگیرد.'
 start=content.index(old);end=content.index('\n## ۱۲.',start)
 content=content[:start]+'''ارجاع‌ها و کتابنامه اصلاح شده‌اند. نسخهٔ تحویل شامل مقاله، گزارش، جدول ۶۷ مورد و بستهٔ قابل بازحساب شواهد است. متن نتیجه، تولید عدد هدف را با درصد تأییدشدهٔ پذیرش معنایی ادعای غلط یکسان معرفی نمی‌کند. گزارش بررسی دستی نویسنده و محدودیت نمونه نیز همراه همان نسخه ارائه می‌شود.
'''+content[end:]
 start=content.index('## ۱۲. کارهای باقیمانده و ترتیب تکمیل');end=content.index('\n## ضمیمهٔ الف.',start)
 content=content[:start]+'''## ۱۲. تصمیم عملی دربارهٔ پنج نقد باقی‌مانده

| نقد | اقدام این نسخه | حدی که حفظ شده است |
|---|---|---|
| اعتبار تفسیر معنایی | بررسی دستی معنایی نویسنده بر ۷۲ مورد با یافته‌ها و نمونه‌های مشخص گزارش شد. | درصد موفقیت معنایی برای کل پاسخ‌ها و توافق ارزیابان ادعا نشده است. |
| عیب واقعی بعضی مرجع‌های B | B به شاهد تشخیصی پسینی محدود شد؛ نتیجهٔ اصلی بر C و کنترل‌های آن استوار است. ۵ ابهام، ۶ اصلاح و ۱۰ مقدار با نادرستی ثابت‌نشده با هم‌پوشانی خود حفظ شدند. | خطای مرجع با حذف خاموش یا تغییر معنای سؤال اصلاح‌شده معرفی نمی‌شود؛ حساسیت ۵۰موردی جای مخرج اصلی را نمی‌گیرد. |
| آرشیو تاریخی A | A فقط به‌عنوان زمینهٔ تاریخی نگه داشته شد؛ ورودی‌های موجود و حدود جست‌وجو منتشر می‌شوند. | بازتولید خروجی تاریخی ادعا نمی‌شود و C جانشین اجرای A نامیده نشده است. |
| دسترسی مستقل به شواهد | کد، داده، پاسخ‌های خام، زمینه‌ها، بردارها، هش‌ها و دستور بررسی بدون API در ریپو قرار می‌گیرند. | راستی‌آزمایی محاسبات و تمامیت فایل با تأیید مستقل همهٔ حقایق منبع یکسان نیست. |
| دامنهٔ تعمیم | نتیجه به ۶۲ پرسش، یک snapshot مدل، حملهٔ قالبی و ماژول‌های ثبت‌شده محدود شد. | ادعای تعمیم به مدل‌های دیگر، همهٔ موضوع‌ها یا استقرار نهادی حذف شده است. |

برای متخصص، یک لینک GitHub به نسخهٔ مقاله، گزارش، یافته‌های معنایی و مسیر اجرای بررسی شواهد داده می‌شود. پیشرفت این نسخه، ارائهٔ یافته‌های موردی و امکان بررسی مستقل محاسبات است؛ ارقام آزمایش منجمد برای متفاوت‌نشان‌دادن نتیجه تغییر نکرده‌اند. توسعهٔ بعدی می‌تواند منبع، نوع سؤال و مدل بیشتری را بیازماید، اما چنین آزمایشی در این نسخه انجام‌شده معرفی نمی‌شود.
'''+content[end:]
 content=content.replace("| evaluation/human_validation_gate.json | دلایل بازبودن داوری واقعی انسان |", "| manual_review/author_reported_findings.json | گزارش نویسنده از بررسی معنایی ۷۲ مورد و یافته‌های نمونه |")
 content=content.replace('منتظر داوری واقعی انسان','بررسی موردی نویسنده در دامنهٔ جاری ثبت شده')
 content=content.replace('| evaluation/human_review_packet و coordinator_only | فورم اولیهٔ جدا از کلید شرط و فورم مرحلهٔ بعد |','| manual_review/author_reported_findings.json | گزارش تجمیعی نویسنده از۷۲مورد و یافته‌های معنایی |')
 content=content.replace('| evaluation/study_c_review/ | قاب مستقل داوری C و کلید خصوصی اتصال به شرایط و نوبت‌ها |','| assistant_review/selection_freeze.json و pass1_input_*.json | شناسهٔ نمونه‌ها و متن کامل پرسش، پاسخ و شواهد بررسی‌شده |')
 return content
